param([Parameter(Mandatory=$true)][string]$SourcePath,[Parameter(Mandatory=$true)][string]$HeaderPath,[Parameter(Mandatory=$true)][string]$TestPath,[Parameter(Mandatory=$true)][string]$HypervisorCMake,[Parameter(Mandatory=$true)][string]$TestsCMake,[Parameter(Mandatory=$true)][string]$ForbiddenPaths)
$ErrorActionPreference='Stop';function A($x,$m){if(-not$x){throw$m}};function V($s,$h,$t,$hc,$tc){foreach($x in @('VmxCr3ControlsEnable(','VmxCr3ControlsAppendTargetCount(','hardware-forced CR3-store-exiting bit is preserved','explicit CR3-target count of zero')){A($h.Contains($x))"header $x"};foreach($x in @('ControlsValid(Base)','!Zero(OutControls, sizeof(*OutControls))','Base->PrimaryControls & CPU_BASED_CR3_LOAD_EXITING','PrimaryAllowed & CPU_BASED_CR3_LOAD_EXITING','Staged.PrimaryControls |= CPU_BASED_CR3_LOAD_EXITING','*OutControls = Staged','PlanValid(Plan)','VmxVmcsPlanAddWrite(&Staged, VMCS_CTRL_CR3_TARGET_COUNT, 0)','*Plan = Staged')){A($s.Contains($x))"source $x"};A($s-notmatch'(?i)ntddk|wdm\.h|wdf\.h|__vmx|vmread|vmwrite|invept|IOCTL|Dispatcher')'pure';foreach($x in @('enable load exiting','store bit clear','hardware-forced store accepted','forced store preserved','forced store gains load','forced store target count','target-count field','target-count zero','invalid base','pre-enabled load','load exit unsupported','unsupported capability preserves','duplicate target count','VMCS plan preserves')){A($t.Contains($x))"test $x"};A(([regex]::Matches($hc,'(?m)^\s*vmx_cr3_control_policy\.c\s*$')).Count-eq1)'source once';A(([regex]::Matches($tc,'add_test\(NAME test_vmx_cr3_control_policy COMMAND')).Count-eq1)'unit once';A(([regex]::Matches($tc,'test_vmx_cr3_control_policy_contracts')).Count-eq1)'contract once'}
$s=Get-Content -Raw $SourcePath;$h=Get-Content -Raw $HeaderPath;$t=Get-Content -Raw $TestPath;$hc=Get-Content -Raw $HypervisorCMake;$tc=Get-Content -Raw $TestsCMake;V $s $h $t $hc $tc;foreach($p in $ForbiddenPaths.Split(',')){A((Get-Content -Raw $p)-notmatch'VmxCr3Controls|vmx_cr3_control_policy')"unwired $p"};$m=@($s.Replace('ControlsValid(Base)','1'),$s.Replace('!Zero(OutControls, sizeof(*OutControls))','0'),$s.Replace('Base->PrimaryControls & CPU_BASED_CR3_LOAD_EXITING','Base->PrimaryControls & 0'),$s.Replace('PrimaryAllowed & CPU_BASED_CR3_LOAD_EXITING','PrimaryAllowed & 0'),$s.Replace('Staged.PrimaryControls |= CPU_BASED_CR3_LOAD_EXITING','Staged.PrimaryControls = Base->PrimaryControls'),$s.Replace('VmxVmcsPlanAddWrite(&Staged, VMCS_CTRL_CR3_TARGET_COUNT, 0)','1'),$s.Replace('*Plan = Staged','memset(Plan,0,sizeof(*Plan))'));$i=0;foreach($x in $m){$i++;A($x-ne$s)"vacuous $i";$bad=$false;try{V $x $h $t $hc $tc}catch{$bad=$true};A($bad)"accepted $i"};Write-Host 'PASS: CR3 control policy enables load exits, preserves hardware-forced store exits, appends target-count zero, and remains transactionally guarded.'
